DO $$
DECLARE
    v_subject_id UUID;
    v_chapter_id UUID;
BEGIN
    -- 1. Insert or get Subject
    SELECT id INTO v_subject_id FROM subjects WHERE name_en = 'ICT' OR name_en = 'Information and Communication Technology' LIMIT 1;
    IF v_subject_id IS NULL THEN
        INSERT INTO subjects (name_bn, name_en, icon_url)
        VALUES ('তথ্য ও যোগাযোগ প্রযুক্তি', 'ICT', 'https://img.icons8.com/color/96/laptop.png')
        RETURNING id INTO v_subject_id;
        RAISE NOTICE 'Created Subject: ICT (%)', v_subject_id;
    ELSE
        UPDATE subjects
        SET name_bn = 'তথ্য ও যোগাযোগ প্রযুক্তি', icon_url = 'https://img.icons8.com/color/96/laptop.png'
        WHERE id = v_subject_id;
    END IF;

    -- ======================================================
    -- Chapter 1: ICT and Our Bangladesh
    -- ======================================================
    IF NOT EXISTS (SELECT 1 FROM chapters WHERE subject_id = v_subject_id AND order_index = 1) THEN
        INSERT INTO chapters (subject_id, title_bn, title_en, order_index)
        VALUES (v_subject_id, '১ম অধ্যায়: তথ্য ও যোগাযোগ প্রযুক্তি ও আমাদের বাংলাদেশ', 'ICT and Our Bangladesh', 1)
        RETURNING id INTO v_chapter_id;
    ELSE
        UPDATE chapters SET title_bn = '১ম অধ্যায়: তথ্য ও যোগাযোগ প্রযুক্তি ও আমাদের বাংলাদেশ', title_en = 'ICT and Our Bangladesh'
        WHERE subject_id = v_subject_id AND order_index = 1
        RETURNING id INTO v_chapter_id;
    END IF;

    DELETE FROM lessons WHERE chapter_id = v_chapter_id;

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, $tag_ict_ch01$
# ১ম অধ্যায়: তথ্য ও যোগাযোগ প্রযুক্তি ও আমাদের বাংলাদেশ

**তথ্য ও যোগাযোগ প্রযুক্তি • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*একুশ শতক এবং তথ্য ও যোগাযোগ প্রযুক্তির বিকাশ, উল্লেখযোগ্য ব্যক্তিত্ব, ই-লার্নিং, ই-গভর্ন্যান্স, ই-সেবা, ই-কমার্স এবং কর্মক্ষেত্রে আইসিটি।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> তথ্য ও যোগাযোগ প্রযুক্তির গুরুত্ব ব্যাখ্যা করতে পারবঃ
> তথ্য ও যোগাযোগ প্রযুক্তি সংশ্লিষ্ট ব্যক্তিবর্গের অবদান বর্ণনা করতে পারব;
> বাংলাদেশে ই-লার্নিংয়ের গুরুত্ব ব্যাখ্যা করতে পারব;
> বাংলাদেশে ই-গভর্ন্যান্সের প্রয়োজনীয়তা ব্যাখ্যা করতে পারব;
> বাংলাদেশে ই-সার্ভিসের গুরুত ব্যাখ্যা করতে পারব;
> বাংলাদেশে ই-কমার্সের গুরুত্ব বর্ণনা করতে পারব;
> বাংলাদেশে কর্মক্ষেত্রে তথ্য ও যোগাযোগ প্রযুক্তির সম্তাবনা বিশ্লেষণ করতে পারব;
> সামাজিক যোগাযোগে তথ্য ও যোগাযোগ প্রযুক্তির ভূমিকা ব্যাখ্যা করতে পারব;
> বিনোদনের ক্ষেত্রে আইসিটির ইতিবাচক দিকগুলো ব্যাখ্যা করতে পারব;
> “তথ্য ও যোগাযোগ প্রযুত্তিনির্ভর বাংলাদেশ' বিষয়ক একটি পোস্টার ডিজাইন করতে পারব।

### 🔹 বিষয়: একুশ শতক এবং তথ্য ও যোগাযোগ প্রযুক্তি
বিগত শতাব্দীতে সম্পদের যে ধারণা ছিল, একুশ শতকে এসে সেটি পুরোপুরি পাল্টে গেছে। পৃথিবীর সবাই
মেনে নিয়েছে যে, একুশ শতকের সম্পদ হচ্ছে জ্ঞান | যার অর্থ কৃষি, খনিজসম্পদ কিংবা শক্তির উৎস নয়,
শিল্প কিংবা বাণিজ্যও নয় এখন পৃথিবীর সম্পদ হচ্ছে সাধারণ মানুষ | তার কারণ শুধু মানুষই জ্ঞান অন্বেষণ
করতে পারে, জ্ঞান ধারণ করতে পারে এবং জ্ঞান ব্যবহার করতে পারে | পৃথিবীর সম্পদের এই নতুন ধারণাটি
সারা পৃথিবীতেই মানুষের চিন্তাভাবনার জগৎ পাল্টে দিয়েছে । পৃথিবীর মানুষ এখন একুশ শতকের মুখোমুখি
হওয়ার জন্যে আলাদাভাবে প্রস্তুতি নিতে শুরু করেছে।
আমরা সবাই অনুভব করতে পারছি একুশ শতকের পৃথিবীটা আসলে জ্ঞানভিত্তিক একটা অর্থনীতির ওপর
দীড়াতে শুরু করছে। একুশ শতকে এসে আমরা আরও দুটি বিষয় শুরু করেছি- যার একটি হচ্ছে
Globalization, অন্যটি হচ্ছে Internationalization | এই দুটি বিষয় তৃরান্বিত হওয়ার পেছনের কারণটি
হচ্ছে তথ্য ও যোগাযোগ প্রযুক্তি | যেকোনো দেশের ভৌগোলিক সীমানা বিশ্বায়নের কারণে নিজের দেশের HS
ছাড়িয়ে সারা পৃথিবীতে ছড়িয়ে পড়েছে। ব্যাপারটি বোঝার জন্যে আমরা আমাদের বাংলাদেশের উদাহরণটিই
নিতে পারি | আমাদের দেশের লক্ষ লক্ষ মানুষ এখন সারা পৃথিবীতে ছড়িয়ে-ছিটিয়ে আছে তারা যে যেখানে
আছে সেই অংশটুকুই বাংলাদেশ | এক অর্থে বাংলাদেশের ভৌগোলিক সীমানা ছাড়িয়ে গেছে! আবার বাংলাদেশের
অলিখিত নিয়ম।
আমরা জানি, পৃথিবীর মানুষকে এক সময় বেঁচে থাকার জন্যে পুরোপুরি প্রকৃতির অনুকম্পার ওপর নির্ভর করতে
হতো। মানুষ বিভিন্ন যন্ত্র আবিষ্কার করে প্রকৃতির ওপর নির্ভরশীলতা কমিয়ে এনেছে। অক্টাদশ থেকে উনবিংশ
শতাব্দীতে শিল্প বিগ্রেবের পর মানুষ যন্ত্রের ওপর নির্ভর করে পৃথিবীর অর্থনীতি নিয়ন্ত্রণ করেছে। পৃথিবীর যে সকল
জাতি শিল্প বিগ্রবে অংশ নিয়েছিল, এক সময় তারাই পৃথিবীকে নিয়ন্ত্রণ করেছে। একুশ শতকে যখন জ্ঞানভিত্তিক
অর্থনীতির সূচনা হয়েছে, তখন আবার সেই একই ব্যাপার ঘটছে। যারা জ্ঞানভিত্তিক সমাজ তৈরি করার বিপ্লবে
অংশ নেবে তারাই পৃথিবীর চালিকাশক্তি হিসেবে কাজ করবে |
এই নতুন বিপ্লবে অংশ নিতে হলে রী:
বিশেষ এক ধরনের প্রস্তুতি নিতে | &
হবে সেটি আমরা অনুভব করতে
পারি। যদি আমরা বেঁচে থাকার
সুনির্দিষ্ট দক্ষতাগুলো দেখতে চাই
তাহলে সেগুলো হবে পারস্পরিক
সহযোগিতার মনোভাব, যোগাযোগ
সমাধানে পারদর্শিতা, বিশ্লেষণী চিন্তন
দক্ষতা (critical thinking),
সৃজনশীলতা এবং তার সাথে তথ্য ও
যোগাযোগ প্রযুক্তিতে পারদর্শিতা |

নিচ্ছে। বর্তমানে কৃত্রিম বুদ্ধিমত্তা (AI) ব্যবহার করে অনেক গুরুত্ৃপূর্ণ কাজ সহজে ও দ্রুত করে ফেলা যাচ্ছে।
একুশ শতকে টিকে থাকতে হলে সবাইকে তথ্য ও যোগাযোগ প্রযুক্তির গুরুত্ব্পৃণ বিষয়গুলো জানতে হবে ।
এ বিষয়গুলো জানা থাকলেই একজন এটি ব্যবহার করে তার বিশাল বৈচিত্র্যের জগতে প্রবেশ করতে পারে।
একজন শিক্ষার্থী যতক্ষণ পর্যন্ত এই প্রযুক্তি ব্যবহারে অভ্যস্ত না হবে-ততক্ষণ পর্যন্ত সে তথ্য সংগ্রহ, বিশ্লেষণ,
সংযোজন, মূল্যায়ন করে নতুন তথ্য সৃষ্টি করতে পারবে না। এই দক্ষতা অর্জন করতে না পারলে সে একুশ
শতকের চ্যালেঞ্জ মোকাবিলা করে জ্ঞানভিত্তিক সমাজে স্থান করে নিতে পারবে না |
নির্মাতার অবদান । তার যুক্ত এবং তার বিহীন যোগাযোগ ব্যবস্থা, কম্পিউটারের গণনা ক্ষমতা বৃদ্ধি এবং
মাইকোইলেকট্রনিক্সের বিকাশ বর্তমানে আইসিটিকে হাতের মুঠোয় মধ্যে নিয়ে এসেছে।
আধুনিক কম্পিউটারের বিকাশ বা প্রচলন শুরু হয় চার্লস ব্যাবেজ
(Charles Babbage) [১৭৯১-১৮৭১] নামে একজন ইংরেজ
প্রকৌশলী ও গণিতবিদের হাতে । অনেকে তাকে আধুনিক
কম্পিউটারের জনক বলে থাকেন। তিনি তৈরি করেন ডিফারেনস
ইঞ্জিন। পরবর্তীতে তিনি এনালিটিক্যাল ইঞ্জিন নামে একটি গণনা
যন্ত্রের পরিকল্পনা করেন। ১৯৯১ সালে লন্ডনের বিজ্ঞান জাদুঘর চার্লস
ব্যাবেজের যন্ত্রের বর্ণনা অনুসারে একটি ইঞ্জিন তৈরি করা হয়।
### 👤 চার্লস ব্যাবেজ (Charles Babbage: ১৭৯১-১৮৭১) — আধুনিক কম্পিউটারের জনক
তবে গণনার কাজটি কীভাবে আরও কার্যকর করা যায় সেটি নিয়ে
ভেবেছিলেন কবি লর্ড বায়রনের কন্যা অ্যাডা লাভলেস (Ada
Lovelace) (১৮১৫-১৮৫২)। মায়ের কারণে তিনি ছোটোবেলা থেকে
বিজ্ঞান ও গণিতে আগ্রহী হয়ে ওঠেন | ১৮৩৩ সালে চার্লস ব্যাবেজের
ইঞ্জিনকে কাজে লাগানোর জন্য 'প্রোগ্রামিং-এর ধারণা সামনে নিয়ে
আসেন। এ কারণে অ্যাডা লাভলেসকে প্রোগ্রামিং ধারণার প্রবর্তক
হিসেবে সম্মানিত করা হয়। ১৮৪০ সালে চার্লস ব্যাবেজ তুরিন
বিশ্ববিদ্যালয়ে তার ইঞ্জিন সম্পর্কে বক্তব্য দেন। সে সময় আ্যাডা
কাজের ধারাটি ধাপ অনুসারে ক্রমাঙ্িকিত করেন ।তার মৃত্যুর ১০০ বছর
পর ১৯৫৩ সালে সেই নোট আবারো প্রকাশিত হলে বিজ্ঞানীরা বুঝতে

বিজ্ঞানী জেমস ক্লার্ক ম্যাক্সওয়েল (James Clerk Maxwell)
(১৮৩১-১৮৭৯) তড়িৎ চৌম্বকীয় বলের ধারণা প্রকাশ করেন।
তড়িৎ চৌম্বকীয় বলের ধারণা বিনা তারে বার্তা প্রেরণের সম্ভাবনা
সৃষ্টি করে।
### 👤 স্যার জগদীশ চন্দ্র বসু (Jagadish Chandra Bose: ১৮৫৮-১৯৩৭) — অতিক্ষুদ্র তরঙ্গ ও বেতার
বিনা তারে এক স্থান থেকে
অন্য স্থানে বার্তা প্রেরণে
প্রথম সফল হন বাঙালি
বিজ্ঞানী জগদীশচন্দ্র বসু
(Jagadish Chandra
Bose) (১৮৫৮-১৯৩৭)। ১৮৯৫ সালে জগদীশচন্দ্র বসু অতিক্ষুদ্র
তরঙ্গ ব্যবহার করে এক স্থান থেকে অন্য স্থানে তথ্য প্রেরণে সক্ষম
