কোম্পানিতে যোগ দেওয়ার পাশাপাশি নিজেরা কোম্পানি গড়ে তুলছে এবং বিশাল সংখ্যক তরুণ-তরুণী
২০১৮ সালের ১২ই মে তারিখটি আমাদের জন্য খুবই গুরুত্বপূর্ণ | এদিনে বাংলাদেশ বিশ্বের ৫৭তম রাষ্ট্র হিসেবে
তার নিজদ্ব স্যাটেলাইট বাংলাদেশ স্যাটেলাইট-১ মহাকাশে প্রেরণ করে। এতে ডিজিটাল বাংলাদেশ বাস্তবায়নে
দেশ আরও একধাপ এগিয়ে গেল। স্যাটেলাইটটি ব্যবহার করে শিক্ষা, চিকিৎসা, কৃষি, আবহাওয়ার পূর্বাভাস নানা
ক্ষেত্রে সুফল পাওয়ার পাশাপাশি বাংলাদেশ অর্থনৈতিক অগ্গতি লাভ করছে। টেলিভিশন সেবা ও জাতীয়
নিরাপত্তার কাজেও এ স্যাটেলাইটটি ব্যবহার করা হচ্ছে। বাংলাদেশের যেকোনো প্রাকৃতিক CAA মোকাবিলা
ও ব্যবস্থাপনায় নতুন মাত্রা যোগ হয়েছে। এছাড়াও বাংলাদেশ স্যাটেলাইট -১ এর কারণে তথ্য ও যোগাযোগ প্রযুক্তি
ব্যবহারের ক্ষেত্রে অর্থ সাশ্রয়ের সাথে সাথে প্রচুর পরিমাণে বৈদেশিক মুদ্বা আয়ও সম্ভব হচ্ছে।
