### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: একুশ শতকে পৃথিবীর সবচেয়ে গুরুত্বপূর্ণ সম্পদ কী এবং কেন?**
> 💡 **উত্তর:** একুশ শতকের সবচেয়ে গুরুত্বপূর্ণ সম্পদ হলো 'জ্ঞান' এবং সেই জ্ঞানকে ধারণকারী সাধারণ মানুষ। কারণ শুধুমাত্র মানুষই নতুন জ্ঞান অন্বেষণ, ধারণ ও ব্যবহার করে সমস্যা সমাধান করতে এবং নতুন সম্ভাবনা সৃষ্টি করতে পারে।

> ❓ **প্রশ্ন: চার্লস ব্যাবেজ ও অ্যাডা লাভলেসের অবদান কী?**
> 💡 **উত্তর:** চার্লস ব্যাবেজ আধুনিক কম্পিউটারের জনক, যিনি 'ডিফারেন্স ইঞ্জিন' ও 'অ্যানালিটিক্যাল ইঞ্জিন' পরিকল্পনা করেছিলেন। অন্যদিকে কবি লর্ড বায়রনের কন্যা অ্যাডা লাভলেস চার্লস ব্যাবেজের ইঞ্জিনের জন্য প্রথম প্রোগ্রামিং অ্যালগরিদম রচনা করেন, যার কারণে তাকে ইতিহাসের প্রথম কম্পিউটার প্রোগ্রামার হিসেবে গণ্য করা হয়।

> ❓ **প্রশ্ন: ই-গভর্ন্যান্স ও ই-সেবা বলতে কী বোঝায়?**
> 💡 **উত্তর:** সরকারি কাজকর্ম, ফাইল ব্যবস্থাপনা ও নীতিমালায় তথ্যপ্রযুক্তির প্রয়োগকে ই-গভর্ন্যান্স বলে। এর মাধ্যমে জনগণ ঘরে বসেই বিভিন্ন সেবা (যেমন: ই-পর্চা, ই-পুর্জি, ডিজিটাল স্বাস্থ্যসেবা, অনলাইনে বিল পরিশোধ ও টিকেট সংগ্রহ) সহজে ও দ্রুত গ্রহণ করতে পারে।

