# ২য় অধ্যায়: কম্পিউটার রক্ষণাবেক্ষণ ও সাইবার নিরাপত্তা

**তথ্য ও যোগাযোগ প্রযুক্তি • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*ডিজিটাল ডিভাইস রক্ষণাবেক্ষণ, সফটওয়্যার ইনস্টল ও আনইনস্টল, ডিস্ক ক্লিনআপ, ভাইরাস ও অ্যান্টিভাইরাস, পাসওয়ার্ড সুরক্ষা, সাইবার অপরাধ এবং কম্পিউটার ট্রাবলশুটিং গাইড।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> Software uninstall এবং Software delete -এর পার্থক্য করতে পারব;
> অতিমাত্রায় ইন্টারনেট ব্যবহারের ফলাফল বিশ্লেষণ করতে পারব;
> সফটওয়্যার পাইরেসির বিষয়টি বর্ণনা করতে পারব;

> কপিরাইট আইনের গুরুত্ব ব্যাখ্যা করতে পারব;
> কম্পিউটারের ট্রাবল শ্যুটিং-এর গুরুত্ব ব্যাখ্যা করতে পারব;
> কম্পিউটারের সাধারণ সমস্যার ট্রাবলশ্যুট করতে পারব।
কম্পিউটার রক্ষণাবেক্ষণ
কম্পিউটার হচ্ছে কিছু ইলেক্ট্রনিক যন্ত্রাংশ (হার্ডওয়্যার) ও সফটওয়্যারের সমন্বিত HA | সুতরাং এর থেকে ভালো
সেবা (সার্ভিস) পেতে হলে একে অবশ্যই পরিচর্যা করতে হবে। বাইরের বিভিন্ন নিয়ামক যেমন: আর্দ্রতা,
তাপমাত্রা, বিদ্যুৎক্ষেত্র, চুম্বকক্ষেত্র,ধুলিকণা, ধোয়া, পানি ইত্যাদির প্রভাব থেকে কম্পিউটারকে রক্ষা করতে
হবে । পাশাপাশি এর মধ্যে থাকা অপারেটিং সিস্টেম ও ত্যাপ্রিকেশন সফটওয়্যারও আপডেটেড রাখতে হবে ।
বুঝায় | কম্পিউটারের রক্ষণাবেক্ষণ দুই প্রকারের হতে পারে | যথা-
> | প্রতিরোধমুলক রক্ষণাবেক্ষণ (Preventive Maintenance) : কম্পিউটারের ফল্ট (fault) বা সমস্যা
তৈরি হওয়ার পূর্বেই সতর্কতামূলক ব্যবস্থা নেওয়াকে প্রতিরোধমূলক রক্ষণাবেক্ষণ বলা হয়। ব্যবহারকারী নিজে
সফটওয়্যার আপডেট ইত্যাদি |
২। সংশোধনমূলক রক্ষণাবেক্ষণ (Corrective Maintenance) : কম্পিউটারের ফল্ট বা সমস্যা তৈরি
হওয়ার পর তা মেরামত বা পরিবর্তন করে কম্পিউটারকে কর্মক্ষম করাকে সংশোধনমূলক রক্ষণাবেক্ষণ বলা হয়।
সংশোধনমূলক রক্ষণাবেক্ষণের জন্য সাধারণত কম্পিউটার টেকনিশিয়ানের সাহায্যের প্রয়োজন হয় | আরেকটি
