বাবা প্রথম সাময়িকের ফল ভালো হওয়ায় রায়নাকে কোর আই ফাইভ প্রসেসরযুত্ত একটি ল্যাপটপ
কিনে দিলেন। ল্যাপটপ পেয়ে এবং এর গতি দেখে রায়না যুগ্ধ। সে কিছুদিনের মধ্যেই অনেক সফটওয়্যার
ইনস্টল করে ফেললো। কিন্তু বায়না লক্ষ করলো তার ল্যাপটপটি আস্তে আস্তে ধীরগতির হয়ে যাচ্ছে। এক
