সুরক্ষিত। যেমন: বাণিজ্যিক চুক্তি, জাতীয় পরিচয়পত্র, পাসওয়ার্ড ইত্যাদি | অনুমতি ছাড়া গোপনীয় তথ্য প্রকাশ
চতুর্থ শিল্প বিপ্লবের এই যুগে আমাদের বিভিন্ন প্রয়োজনে ব্যক্তিগত তথ্য প্রদানের মাধ্যম হিসেবে ডিজিটাল প্রযুক্তি
ব্যবহার করতে হয়। এখানে ডিজিটাল প্রযুক্তি বলতে তথ্য যোগাযোগ, হিসাব-নিকাশ ও অটোমেশনের মতো
কাজগুলো সুচারুরূপে সম্পন্ন করতে প্রয়োজনীয় ইলেকট্রনিক যন্ত্রপাতি বা ডিভাইস ও সিস্টেমকে বোঝায় যা
বাইনারি আকারে ডেটা প্রক্রিয়াকরণ, সংরক্ষণ এবং প্রেরণ করতে পারে |
ডিজিটাল প্রযুক্তির এই প্রসারের ফলে, বিভিন্ন ধরনের সাইবার অপরাধের মাধ্যমে তথ্য নিরাপত্তা ঝুঁকিতে পড়ে
মানুষ প্রতারণার শিকার হচ্ছে। সাইবার জগৎ হলো একটি ডিজিটাল স্থান যেখানে মানুষ একে অপরের সাথে

ইন্টারনেটের মাধ্যমে যোগাযোগ করতে পারে এবং তথ্য পেতে পারে | এটি বাহ্যিক জগতের সমান্তরাল এমন
একটি জগৎ যা ইন্টারনেট, ডেটা এবং কোড দ্বারা গঠিত। সাইবার জগৎ ক্রমাগত বর্ধিত ও বিকশিত
হচ্ছে এবং এটি আমাদের জীবনের একটি অপরিহার্য অংশ হয়ে উঠেছে।
### 🔹 বিষয়: সাইবার অপরাধ (Cyber Crime: ব্রুট ফোর্স অ্যাটাক, ফিশিং)
