ডিজিটাল মাধ্যমে বিভিন্ন ধরনের সাইবার অপরাধ রয়েছে, যার মাধ্যমে তথ্যের নিরাপত্তার ঝুঁকি তৈরি হয়। নিচে
কিছু সাইবার অপরাধ উল্লেখ করা হলো |
= হ্যাকিং (Hacking)
= ক্রুট ফোর্স আ্যাটাক (Brute Force Attack)
"ডেটা ইন্টারসেপশন (Data Interception)
= ডি ডস ত্যাটাক (DDos Attack)
