হ্যাকিং (Hacking)
সাধারণত অনুমতি ব্যতীত কোনো ওয়েবসাইট বা কম্পিউটার নেটওয়ার্কে প্রবেশ করে তা ব্যবহার করা অথবা তার পুরো
নিয়ন্ত্রণ নিয়ে নেওয়াকে হ্যাকিংবলে। যে হ্যাকিং করে তাকে হ্যাকার (Hacker) বলে। হ্যাকিং বৈধ ও অবৈধ হতে পারে |
কিছু প্রতিষ্ঠান তাদের সিস্টেমের সিকিউরিটি পরীক্ষা-নিরীক্ষার জন্য হ্যাকার নিয়োগ করেন। এই নিয়োগ প্রাপ্ত
হ্যাকারদের কাজকে বৈধ হ্যাকিং বলে | এরা সিস্টেম সিকিউরিটি চেক করে; তবে সিস্টেমের কোন ক্ষতি করে না। যেমন-
UNIX সিস্টেম চেক করার জন্য অনেক বৈধ হ্যাকার রয়েছে। এদেরকে হোয়াইট হ্যাট হ্যাকার বলা হয়। অবৈধভাবে
যারা হ্যাকিং করে তাদেরকে ক্রেকার (0181591-)ও বলে | অবৈধ হ্যাকার বা ক্রেকাররা ইন্টারনেট ও অন্যান্য নেটওয়ার্ক
ব্যবহার করে ডেটা চুরি অথবা নষ্ট করে HT | এদের কাছে সাধারণত বেশ কিছু টেকনিক থাকে যা ব্যবহার করে এরা
ইন্টারনেটের মাধ্যমে সফটওয়্যার সিস্টেমের দুর্বলতা খুব সহজে খুঁজে
পারে | এদেরকে ব্যাক হ্যাট হ্যাকার বলে।
হ্যাকিং অপরাধের প্রবণতা দিনদিন বেড়েই চলেছে। হ্যাকিংয়ের
মাধ্যমে সাইবার অপরাধ সংঘটিত হয়। হ্যাকাররা অন্যের ইমেইল
অথবা নেটওয়ার্কে ফাইল চুরি করতে পারে |

St ফোর্স আাটাক (Brute Force Attack)
খোলার চেষ্টা করে, তেমনি ডিজিটাল মাধ্যমে অপরাধীরা মানুষের বিভিন্ন ধরনের অ্যাকাউন্ট যেমন ব্যাংক,
জন্য বিভিন্ন ধরনের সফটওয়্যার ব্যবহার করে এবং এ গুলো নিয়ে একের পর এক অনুমান নির্ভর চেষ্টা করে।
মাঝে মাঝে তারা সফলও হয় এবং সফল হলে তারা এ ব্যক্তির বিভিন্ন ব্যক্তিগত তথ্য চুরি করে । এ চুরি করা
ব্যক্তিগত তথ্য ব্যবহার করে তারা বিভিন্ন ধরনের অপরাধ করে থাকে | এটি এক ধরনের সাইবার আক্রমণ যা
অবশ্যই একটি গুরুতর সাইবার অপরাধ | এই ধরনের সাইবার হামলা HO ফোর্স আযাটাক (Brute Force
Attack) নামে পরিচিত।
