ডেটা ইন্টারসেপশন (Data Interception)
কৃষিকাজের জন্য জমিতে পানি সেচ দেওয়ার ক্ষেত্রে সাধারণত পানির পাম্প থেকে জমি বা ক্ষেত-এ নালা করে
অথবা পাইপের সাহায্যে পানি দেওয়া হয়। এই নালা বা পাইপের মাঝপথে যদি কেউ তা কেটে দেয় অথবা পানির
পাইপটি ফুটো করে দেয়, তাহলে যে পরিমাণ পানি পাওয়ার কথা তা পাওয়া যাবে A | এর ফলে কৃষক ক্ষতিথত্ত
হবে । মাঝপথে পানি অসৎ উপায়ে যেন কেউ না নিতে পারে তার জন্য নজরদারির ব্যবস্থা করতে হবে । ঠিক
একইভাবে ডিজিটাল মাধ্যমে তথ্য আদান প্রদানের সময় প্রাপক এবং প্রেরকের মধ্যবর্তী কেউ তা আড়ি পেতে
চুরি করতে পারে | এই চুরি হবার প্রক্রিয়াটি ডেটা ইন্টারসেপশন নামে পরিচিত।
