অনুপ্রবেশকারী
সাধারণত সফটওয়্যার বা আযাপস-এ এন্ড টু এন্ড ডেটা এনক্রিপশন করা থাকলে, মধ্যবর্তী কারও পক্ষে তথ্য
(ম্যাসেজ, ছবি, ভিডিয়ো, ভয়েস কল রেকর্ড, ডকুমেন্ট ইত্যাদি) চুরি করা অসম্ভব হয়ে যায় ।আ্যানক্রিপশন
(Encryption) হলো মেসেজ, ডেটা বা তথ্যকে এনকোড করার এমন একটি বিশেষ প্রক্রিয়া যা অনুমোদনহীন
কেউ পড়তে বা বুঝতে পারে না | এর ফলে অনুমোদনহীনদের কাছে মেসেজ, ডেটা বা তথ্য দুর্বোধ্য হয়ে থাকে।
নেটওয়ার্কের পাবলিক পথ দ্বারা যে সকল গোপনীয় ডেটা ছ্থানান্তরিত হয় তাদেরকে সাধারণত বিশেষ কোডের
মাধ্যমে এনক্রিস্ট করে প্রেরণ করা হয়। অর্থাৎ ডেটার গোপনীয়তা রক্ষা বা সিকিউরিটির জন্য ডেটাকে এনক্রিপ্ট
করা হয়।
ডি WF আক্রমণ (DDoS-Distributed Denial of Service)
কোনো ব্যক্তি যখন টিভিতে সাক্ষাৎকার দেয় তখন অনেকেই যদি একসাথে অনেকগুলো প্রশ্ন ওই ব্যক্তিকে করেন
