মোবাইল, কম্পিউটার, সার্ভার, ওয়েবসাইট অথবা কম্পিউটার নেটওয়ার্কের ক্ষতি করার জন্য ডিজাইন ও
উন্নয়ন করা হয়েছে এমন সফটওয়্যারকে ম্যালওয়্যার বলে।
এই সফটওয়্যার মোবাইল, কম্পিউটার বা অন্য কোনো ডিজিটাল সিস্টেম ব্যবহারকারীর স্বার্থের বিরুদ্ধে কাজ
করে। তবে যদি কোনো সফটওয়্যার তার অক্ষমতার কারণে অনিচ্ছাকৃতভাবে কম্পিউটার সিস্টেমে কোনো
অসুবিধা সৃষ্টি করে সেক্ষেত্রে তাকে ম্যালওয়্যার বলা চলে না; একে সফটওয়্যার বাগ (bug) বলা হয়।
ম্যালওয়্যার এমন এক জাতীয় ক্ষতিকর সফটওয়্যার যা কম্পিউটার, মোবাইল বা অন্য কোনো ডিজিটাল
সিস্টেমের স্বাভাবিক কাজকে ব্যাহত করতে, গোপন তথ্য সংগ্রহ করতে, কোনো সংরক্ষিত কম্পিউটার
নেটওয়ার্ক ব্যবস্থায় অবৈধ অনুপ্রবেশ করতে বা অবাঞ্ছিত বিজ্ঞাপন দেখাতে ব্যবহার করা VT | ম্যালওয়্যার বিভিন্ন
ধরনের হতে পারে | যথা- কম্পিউটার ভাইরাস (computer viruses), ওয়ার্ম (worms), ট্রোজান হর্স
(trojan horses), স্পাইওয়্যার (spyware), র্যানসামওয়্যার (ransomware), তআ্যাডওয়্যার
(adware), রুটকিটস্‌ (rootkits) ও স্প্যামিং (spamming) ইত্যাদি |
সাইবার বুলিং (Cyber bullying)
অনলাইন প্লাটফর্ম ব্যবহার করে ইচ্ছাকৃত ও বার বার কাউকে মানসিকভাবে ক্ষতিগ্রস্থ করা যেমন অপমানজনক বার্তা
পাঠানো গুজব ছড়ানো, ব্যক্তিগত তথ্য ফাঁস করা বা কাউকে সামাজিক মাধ্যমে হেয় করাকে সাইবার বুলিং বলে।
সাইবার সন্ত্রাস বলা হয়। কাউকে সামাজিকভাবে হেয় প্রতিপন্ন করা, হুমকি প্রদান করা, আতঙ্ক
সৃষ্টি করা, অনুমতি ব্যতীত কারো ব্যক্তিগত তথ্য বা ছবি সামাজিক মাধ্যমে প্রকাশ করা , সামাজিক মাধ্যমগুলো
লাতে বিভিন্ন স্পর্শকাতর বিষয় সম্পর্কে ভুল তথ্য প্রকাশ করা বা গুজব ছড়ানো, সমাজে বিশৃঙ্খলা সৃষ্টি করা বা
সম্প্রদায়ণত বিদ্বেষ ছড়ানো এ সব কিছুই সাইবার সন্ত্রাসের অন্তর্ভূক্ত
সাইবার সন্ত্রাসের জন্য মোবাইল, কম্পিউটার, ট্যাবলেট ইত্যাদি যন্ত্রাংশ এবং বিভিন্ন সামাজিক যোগাযোগ
মাধ্যম, ওয়েবসাইট, ম্যাসেজ, ই-মেইল ইত্যাদি ব্যবহার করা হয়। ই-মেইলে বা সামাজিক যোগাযোগ মাধ্যমে
বিভিন্ন ধরনের ব্বিতকর ছবি, ভিডিয়ো, আপত্তিকর বা অপমানজনক মন্তব্য দ্বারা ব্যক্তিকে সামাজিকভাবে হেয়
করা হয় এবং ব্যক্তিগত জীবনকে বিপর্যস্ত করা হয়।
সাধারণত শিশু এবং কিশোর-কিশোরী ও তরুণ-তরুণীদের ক্ষেত্রে সাইবার বুলিং বেশি ঘটে থাকে | এর ফলে
যেমন তাদের সামাজিক ও পারিবারিক জীবন ক্ষতিগ্ত্ত হয় তেমনই তাদের ভেতর হীনমন্যতা বোধ, হতাশা,
আতঙ্ক তৈরি হয় । অধিকাংশ ক্ষেত্রে সামাজিক মাধ্যমে বা ওয়েবসাইটে কোনো ছবি,ভিডিয়ো বা তথ্য প্রকাশ
করার পর তা মুছে ফেলা অত্যন্ত কঠিন বা অসম্ভব। আবার ফেইক আইডির ক্ষেত্রে এর উৎস বা প্রকাশকারীর পরিচয়
খুঁজে বের করাও অত্যন্ত কঠিন বা অসম্ভব হয়ে পড়ে | কাজেই আমাদের এ বিষয়ে সতর্ক থাকতে হবে।

ফেইক নিউজ
সংবাদ হিসেবে উপস্থাপিত কোনো মিথ্যা বা বিভ্রান্তিকর তথ্য যা মানুষকে প্রতারিত করা বা মানুষের মতামতকে
প্রভাবিত করার জন্য ইচ্ছাকৃতভাবে ছড়িয়ে দেওয়া হয় তাই-ই ফেইক নিউজ | এটি সম্পূর্ণরূপে বানোয়াট গল্প
বা বিকৃত তথ্যের রূপ নিতে পারে এবং সামাজিক যোগাযোগ মাধ্যম ওয়েবসাইট বা অন্যান্য চ্যানেলের মাধ্যমে
জনসাধারণকে বিভ্রান্ত করা বা একটি নির্দিষ্ট আযাজেন্ডা প্রচার করার জন্য ব্যবহৃত হতে পারে।
সামাজিক যোগাযোগ মাধ্যমের অত্যধিক ব্যবহারের এই যুগে, ফেইক নিউজের বিস্তার অত্যন্ত দ্রুততার সাথে
ঘটছে। ইন্টারনেট ব্যবহার করে প্রচারিত ফেইক নিউজের ফলে পৃথিবীব্যাপী অনেক রাজনৈতিক ও ধর্মীয় সংঘাতের
জন্মা হয়েছে। 'চিলে কান নিয়ে গেছে এমন সংবাদে চিলের পিছে না দৌড়ে সবার আগে কানে হাত দিয়ে দেখা
উচিত। ঠিক একইভাবে অনলাইনে কোনো পোস্ট বা খবর দেখলে তা যাচাই করে বিশ্বাস করা উচিত। সাধারণত
কোনো ব্যক্তি বা প্রতিষ্ঠানের নকল অর্থাৎ ছদ্মনাম ধারণ করে বিভিন্ন ধরনের মিথ্যা খবর বা গুজব রটিয়ে
দেওয়া হয়। বাংলাদেশে তথ্য ও প্রযুক্তি আইন ২০০৬ মোতাবেক সাইবার বুলিং এবং ডিজিটাল প্ল্যাটফর্মে
অর্থদণ্ড বা উভয় দণ্ডে দণ্ডিত হতে পারে।
১। যত দ্রুত সম্ভব ন্যাশনাল হেল্পলাইন ১০৯, ন্যাশনাল ইমার্জেন্সি সার্ভিস ৯৯৯ অথবা আইসিটি হেল্পলাইন-এ
যোগাযোগ করতে হবে।
