নিকটস্থ থানায় একটি সাধারণ ডায়েরি (জিডি) করব। আমাদের দেশে এখন অনলাইনেই জিডি বা সাধারণ
ডায়েরি করা যায়। এ জন্য আমাদের যে কোনো ইন্টারনেট ব্রাউজারের ত্যাড্রেস বারে https://gd.police
gov.bd লিখে সার্চ করতে হবে |
