অনুরোধের প্রেক্ষিতে সংশ্লিষ্ট কর্তৃপক্ষ তাকে তথ্য সরবরাহ করতে বাধ্য থাকেন। এই আইনের মাধ্যমে
জনগণের তথ্য অধিকার নিশ্চিত করা হলে সরকারি, স্বায়ত্তশাসিত ও সংবিধিবদ্ধ সংস্থা এবং সরকারি ও
বিদেশি অর্থায়নে সৃষ্ট বা পরিচালিত বেসরকারি সংস্থার স্বচ্ছতা ও জবাবদিহিতা বৃদ্ধি, দুর্নীতি হ্রাস ও সুশাসন
প্রতিষ্ঠিত হবে। এই আইনে জনগণের তথ্য অধিকার নিশ্চিত করার পাশাপাশি সংস্থাসমূহকে তথ্য সংরক্ষণ
করার নির্দেশনা দেওয়া হয়েছে। ফলে জনগণের যেকোনো বিষয়ে তথ্য প্রাপ্তি সহজ হয়েছে।
