ফর্মা-৬, তথ্য ও যোগাযোগ প্রযুক্তি-৯ম শ্রেণি

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: সফটওয়্যার ডিলিট (Delete) এবং আনইনস্টল (Uninstall)-এর মধ্যে পার্থক্য কী?**
> 💡 **উত্তর:** সফটওয়্যারের আইকন বা ফোল্ডার 'Delete' করলে কেবল শর্টকাট বা ফাইলটি মুছে যায় কিন্তু অপারেটিং সিস্টেমের রেজিস্ট্রি ও সিস্টেম ফাইলগুলো অবশিষ্ট থেকে যায়। পক্ষান্তরে 'Uninstall' করলে সফটওয়্যারটির সকল ফাইল, লাইব্রেরি ও সিস্টেম রেজিস্ট্রির এন্ট্রি পুরোপুরি ক্লিন হয়ে অপসারিত হয়।

> ❓ **প্রশ্ন: ডিস্ক ক্লিনআপ (Disk Cleanup) ও ডিস্ক ডিফ্র্যাগমেন্টার (Disk Defragmenter)-এর কাজ কী?**
> 💡 **উত্তর:** ডিস্ক ক্লিনআপ হার্ডডিস্কের অপ্রয়োজনীয় ক্যাশ, টেম্পোরারি ফাইল ও রিসাইকেল বিনের ফাইল স্ক্যান করে মুছে ফেলে ডিস্কের খালি জায়গা পুনরুদ্ধার করে। আর ডিস্ক ডিফ্র্যাগমেন্টার হার্ডডিস্কের ছড়িয়ে-ছিটিয়ে থাকা ফাইলের খণ্ডগুলোকে সাজিয়ে সুবিন্যস্ত করে, যাতে কম্পিউটার ফাইলগুলো দ্রুত পড়তে পারে ও সামগ্রিক গতি বৃদ্ধি পায়।

> ❓ **প্রশ্ন: শক্তিশালী পাসওয়ার্ড কেন জরুরি এবং এটি কীভাবে তৈরি করতে হয়?**
> 💡 **উত্তর:** সাইবার আক্রমণ ও হ্যাকিং থেকে ডিজিটাল অ্যাকাউন্ট ও ডেটা নিরাপদ রাখতে শক্তিশালী পাসওয়ার্ড আবশ্যক। একটি শক্তিশালী পাসওয়ার্ড তৈরি করতে ছোট ও বড় হাতের অক্ষর (a-z, A-Z), সংখ্যা (0-9) এবং বিশেষ চিহ্নের (@, #, $, %, !) সংমিশ্রণে কমপক্ষে ৮-১২ অক্ষরের একটি অনন্য সিকোয়েন্স ব্যবহার করতে হয়।

