### ✍️ মূল পাঠ্যবইয়ের নমুনা বহুনির্বাচনি প্রশ্ন

1. উইন্ডোজ অপারেটিং সিস্টেমে কোনো সফটওয়্যার পুরোপুরি কম্পিউটার থেকে অপসারণ করতে কোনটি ব্যবহার করা হয়?
ক. Uninstall    খ. Delete
গ. Copy    ঘ. Rename

2. কম্পিউটার হার্ডডিস্কের অপ্রয়োজনীয় ফাইল মুছে জায়গা খালি করার ইউটিলিটি কোনটি?
ক. Disk Cleanup    খ. Disk Defragmenter
গ. Task Manager    ঘ. Firewall

3. ডিস্কের ছড়ানো-ছিটানো ফাইলগুলোকে সারিবদ্ধভাবে সাজিয়ে গতি বাড়ানোর প্রক্রিয়া কোনটি?
ক. Disk Defragmenter    খ. Disk Cleanup
গ. Disk Format    ঘ. Antivirus Scan

4. প্রথম কম্পিউটার ভাইরাস 'Brain' কত সালে আবিষ্কৃত হয়?
ক. ১৯৮৬ সালে    খ. ১৯৯১ সালে
গ. ১৯৭৫ সালে    ঘ. ২০০০ সালে

5. VIRUS শব্দটির পূর্ণরূপ কী?
ক. Vital Information Resources Under Siege    খ. Very Important Resource Unit System
গ. Virtual Information Routine Utility Service    ঘ. Visual Interactive Resource User Standard

6. নিচের কোনটি কম্পিউটার অ্যান্টিভাইরাস সফটওয়্যার নয়?
ক. ট্রোজান হর্স (Trojan Horse)    খ. ক্যাসপারস্কি (Kaspersky)
গ. আভাষ্ট (Avast)    ঘ. নর্টন (Norton)

7. শক্তিশালী পাসওয়ার্ড তৈরির ক্ষেত্রে নিচের কোন নিয়মটি সবচেয়ে কার্যকর?
ক. অক্ষর, সংখ্যা ও বিশেষ চিহ্নের মিশ্রণ    খ. নিজের নাম বা জন্মতারিখ
গ. ধারাবাহিক সংখ্যা (123456)    ঘ. সহজ মোবাইল নম্বর

8. সফটওয়্যার পাইরেসি রোধে এবং নির্মাতাদের মেধাস্বত্ব সুরক্ষায় কোন আইন প্রয়োগ করা হয়?
ক. কপিরাইট আইন (Copyright Law)    খ. ভোক্তা অধিকার আইন
গ. ট্রেডমার্ক আইন    ঘ. শ্রম আইন

9. কম্পিউটারে কোনো হার্ডওয়্যার বা সফটওয়্যার সমস্যার উৎস ও সমাধান নির্ণয়ের প্রক্রিয়াকে কী বলে?
ক. ট্রাবলশুটিং (Troubleshooting)    খ. প্রোগ্রামিং (Programming)
গ. ডিবাগিং (Debugging)    ঘ. এনক্রিপশন (Encryption)

10. কম্পিউটার চালু করার পর মনিটরে কোনো ডিসপ্লে না এলে প্রথমে কী পরীক্ষা করা উচিত?
ক. র‍্যাম (RAM) স্লট ও ক্যাবল সংযোগ    খ. সাউন্ড কার্ড
গ. সিডি রম ড্রাইভ    ঘ. মাউস প্যাড
