# ৩য় অধ্যায়: ইন্টারনেট ও ওয়েব পরিচিতি

**তথ্য ও যোগাযোগ প্রযুক্তি • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*ডিজিটাল কনটেন্টের প্রকারভেদ, ই-বুক ও ই-রিডার, শিক্ষায় ইন্টারনেট ও সার্চ ইঞ্জিন, ওয়েবসাইট, ওয়েব ব্রাউজার, আইপি অ্যাড্রেস ও ইউআরএল (URL)।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> ডিজিটাল কনটেন্টের ধারণা ব্যাখ্যা করতে পারব;
> শিক্ষার ক্ষেত্রে ইন্টারনেটের গুরুত্ব ব্যাখ্যা করতে পারব;
> পাঠ্যবিষয়ে ইন্টারনেট ব্যবহারের ক্ষেত্র চিহ্নিত করতে পারব;
> ক্যারিয়ার উন্নয়নে আইসিটির গুরুত্ব ব্যাখ্যা করতে পারব;

ইন্টারনেট
আমরা ইতোমধ্যে শিখেছি যে ইন্টারনেট হলো বিশ্বব্যাপী eS একটি নেটওয়ার্ক যা সারা বিশ্বের কম্পিউটার
এবং ডিভাইসসমূহকে সংযুক্ত BA | তার বা বেতার মাধ্যমে এটি মানুষ কিংবা ডিভাইসকে তথ্য শেয়ার করতে
এবং একে অপরের সাথে যোগাযোগ করার সুযোগ তৈরি করতে ব্যবহৃত হয়। তাছাড়া ওয়েবসাইট বাউজ
করতে, ইমেল পাঠাতে বা বন্ধুদের সাথে চ্যাট করতেও এটির ব্যবহার পরিলক্ষিত হয়। এতে ডিজিটাল কনটেন্ট
ব্যবহৃত হয়।
### 🔹 বিষয়: ডিজিটাল কনটেন্টের ধারণা ও প্রকারভেদ
কোনো কনটেন্ট যদি ডিজিটাল উপাত্ত আকারে বিরাজ করে, প্রকাশিত হয় কিংবা প্রেরিত-গৃহীত হয় তাহলে
সেটিই ডিজিটাল কনটেন্ট | তবে সেটি ডিজিটাল বা এনালগ যেকোনো পদ্ধতিতেই সংরক্ষিত হতে পারে।
ডিজিটাল কনটেন্ট কম্পিউটারের ফাইল আকারে অথবা ডিজিটাল পদ্ধতিতে সম্প্রচারিত হতে পারে | লিখিত
তথ্য, ছবি, শব্দ কিংবা ভিডিয়ো ডিজিটাল কনটেন্ট হতে পারে। ডিজিটাল কনটেন্ট ব্যবহারের ফলে তথ্য
