ণত HTTP (Hyper ext Transfer Protocol) অথবা HTTPs (Hyper Text Transfer Protocol
Secure) প্রোটোকল ব্যবহার করে ওয়েব সার্ভারের কাছে কোনো উপাত্ত বা তথ্য চেয়ে অনুরোধ (request)
পাঠায়। ক্লায়েন্টের অনুরোধগুলো সাধারণত ওয়েব ব্রাউজারের মাধ্যমে পাঠানো হয় এবং অনুরোধের ফলাফল
