### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ডিজিটাল কনটেন্ট কী এবং এর প্রধান শ্রেণিগুলো কী কী?**
> 💡 **উত্তর:** ডিজিটাল মাধ্যমে কোনো তথ্য, জ্ঞান বা উপাত্ত যখন টেক্সট, ছবি, শব্দ বা ভিডিও আকারে উপস্থাপিত ও সংরক্ষিত হয় তখন তাকে ডিজিটাল কনটেন্ট বলে। এর প্রধান চারটি শ্রেণি হলো: (১) টেক্সট বা লিখিত কনটেন্ট, (২) ছবি বা গ্রাফিক্স, (৩) শব্দ বা অডিও, এবং (৪) ভিডিও ও অ্যানিমেশন।

> ❓ **প্রশ্ন: ই-বুকের বিভিন্ন প্রকারভেদ সংক্ষেপে আলোচনা করো।**
> 💡 **উত্তর:** ই-বুকের প্রধান প্রকারভেদ: (১) মুদ্রিত বইয়ের হুবহু প্রতিলিপি (সাধারণত PDF ফরম্যাট), (২) এইচটিএমএল বা ইপাব (EPUB) ফরম্যাট যা যেকোনো ডিভাইসের স্ক্রিনের সাথে সামঞ্জস্যপূর্ণ হয়, (৩) চৌকস বা ইন্টারেক্টিভ ই-বুক (যাতে টেক্সটের সাথে অডিও, ভিডিও ও কুইজ যুক্ত থাকে), এবং (৪) অ্যাপস আকারে প্রকাশিত ই-বুক।

> ❓ **প্রশ্ন: URL এবং IP Address-এর মধ্যে সম্পর্ক কী?**
> 💡 **উত্তর:** ইন্টারনেটের প্রতিটি কম্পিউটার বা সার্ভারের একটি নির্দিষ্ট সাংখ্যিক ঠিকানা থাকে যাকে IP Address (যেমন: 192.168.1.1) বলে। মানুষের পক্ষে এই জটিল সংখ্যা মনে রাখা কঠিন বিধায় সহজে মনে রাখার জন্য শব্দভিত্তিক ডোমেন নেইম ও URL (যেমন: http://www.shikkha.com) ব্যবহার করা হয়। DNS সার্ভার এই URL-কে ব্যাকএন্ডে আইপি অ্যাড্রেসে রূপান্তর করে ওয়েবপেজ প্রদর্শন করে।

