# ৪র্থ অধ্যায়: আমার লেখালেখি ও হিসাব

**তথ্য ও যোগাযোগ প্রযুক্তি • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*ওয়ার্ড প্রসেসিং সফটওয়্যারে লেখালেখি, ফন্ট ও প্যারাগ্রাফ ফরম্যাটিং, বুলেট ও নাম্বার, টেবিল, মার্জিন এবং স্প্রেডশিটে (এক্সেল) যোগ, বিয়োগ, গুণ, ভাগ ও গড়ের সূত্র।*

---

মানুষের মনের ভাব প্রকাশ করার একটা মাধ্যম হলো লেখালেখি করা। আমাদের প্রয়োজনে আমাদেরকে
নানারকমের লেখালেখি করতে হয়। হতে পারে সেটা কবিতা, গজ, উপন্যাস বা Fee লেখা। লেখালেখি
ছাড়াও আমাদের দৈনদিন জীবনে বিভিন্ন রকমের ছোট-বড় হিসাব করতে হয়। বাজারের হিসাব, বাসাভড়ার
হিসাব, পরীক্ষার ফলাফল ergs ইতযাদি। আমাদের লেখালেখি ও হিসাবের এ কাজগুলো করা এক সময়
কষ্টসাধ্য ছিল। কিনতু তথ্য ও যোগাযোগ প্রযুক্তির বিকাশের ফলে এ কাজগুলো করার জন্য এখন আমাদের
হাতের লাগালে রয়েছে অনেক ধরনের সফটওয়ার এসব সফটওয়ারকে বলা হয় অফিস সফটওয়ার
আমাদের ডেস্কটপ, লাপটপ I RAAT এ সফটওয়ারগুলো বাবহার করা A | লেখালেখির জন্য রয়েছে
রড প্রসেসর আর হিসাবের জনয রয়েছে CRAG এনালাইসিস সফটওয়ার। এগুলো সম্পর্কে তোমরা
পূরবী শ্েখগলোতে প্রাথমিক ধারণ পেয়েছ। এ রেণিতে তোমরা এগলো সম্পর্ক কিছু অগ্রসর ধারা পাবে ।
(কোনোকিছু লেখার কাজ হলো কল্পনার জগৎকে বাস্তব নিয়ে সা। মানু তারকাকে অনোর কাছে তুলে
ধরতে মাধ্যম হিসেবে লেখার কাজ শুরু করে এ ইতিহাস আমরা অনেকেই জানি। বর্তমানে এ কাজে তথ্য ও
যোগাযোগ প্রযুক্তি বত হচ্ছে আর এক্ষরে ওয়ার্ড ্সেসি-এর গর অনেক। টেলিভিশন, মোবাইল ফোন
বা কম্পিউটার ই যনে তথয গ্রহণ ও উপস্থপনের জন্য বেশিরভাগ সময় লিখিত GHC ATER
হয়। আগে যেভাবেই করা হোক না কেন এখন এ কাজটি করা হচ্ছে ওয়ার্ড প্রসেসরের IAG | ওয়ার্ড
প্রসেসরে কাজ করতে গিয়ে আমরা অনেক সুবিধা পেয়ে a | যেমন:
Soul
Reger লেখালেখির কাজ করা হায় এবং ভুল হলে সাথে সাথে সংশোধনের সুযোগ পাওয়া যায়।
* সম্পাদনার সুযোগ থাকায় লেখার কাজ নন্দনিকভাবে উপস্থপন করা যায়।
* নানাভাবে লেখাকে উপস্থাপন TH | যেমন- লেখার আকার ছোট-বড় করা, HA করা, TH আকারে
উপস্থপন করা ইত্াদি।
* পুরো লেখা প্রথম থেকে শুরু না করে নতুন লেখা প্রবেশ করানো, লেখ মুছে ফেলা বা লেখাকে পবিস
করার সুযোগ পাওয়া TH
Spit আল এ লাজ লিল [লিটার
৮ ওয়ার্ড প্রসেসরের গুরুত্বপূর্ণ বৈশিষ্ট ব্যাখ্যা করতে পারব;
> ওয়ার্ড প্রসেসর ব্যবহারের কৌশল বর্ণনা করতে পারব;
> প্রেডশিটর গুরুত্বপূর্ণ বৈশিষ্ট্য ব্যাখ্যা করতে পারব;
> প্পেডশিট ব্যবহারের ক্ষেত্রগুলো চিহ্নিত করতে পারব;
> প্রেডশিট ব্যবহারের কৌশল বর্ণনা করতে পারব;
> ওয়ার্ড প্রসেসর ব্যবহার করে সম্পাদনা করতে পারব;
> PG ব্যবহার করে হিসাব-নিকাশ করতে পারব |

ওয়ার্ড প্রসেসরে আমার লেখার কাজ
নানারকমের লেখালেখি করতে হয় | হতে পারে সেটা কবিতা, গল্প, উপন্যাস বা দিনপঞ্জি লেখা | লেখালেখি
হিসাব, পরীক্ষার ফলাফল প্রস্তুত ইত্যাদি । আমাদের লেখালেখি ও হিসাবের এ কাজগুলো করা এক সময়
