### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ওয়ার্ড প্রসেসরে লেখালেখির প্রধান সুবিধাগুলো কী কী?**
> 💡 **উত্তর:** ওয়ার্ড প্রসেসরে লেখার প্রধান সুবিধা হলো ভুল হলে সহজেই কাটাছেঁড়া ছাড়া সংশোধন করা যায়, লেখার ফন্ট, সাইজ ও রঙ পরিবর্তন করা যায়, স্বয়ংক্রিয় স্পেল চেকার দিয়ে বানান শুদ্ধ করা যায়, টেবিল ও ছবি সংযোজন করা যায় এবং ডকুমেন্টটি নিরাপদে সংরক্ষণ করে যতবার ইচ্ছা প্রিন্ট করা যায়।

> ❓ **প্রশ্ন: স্প্রেডশিটের সেল (Cell), রো (Row) এবং কলাম (Column) বলতে কী বোঝায়?**
> 💡 **উত্তর:** স্প্রেডশিট বা ওয়ার্কশিটে উল্লম্ব বা খাড়া দাগের অংশগুলোকে 'কলাম' (A, B, C ইত্যাদি অক্ষর দ্বারা চিহ্নিত) এবং অনুভূমিক দাগের অংশগুলোকে 'রো' (1, 2, 3 ইত্যাদি সংখ্যা দ্বারা চিহ্নিত) বলা হয়। একটি রো এবং একটি কলামের পরস্পর ছেদবিন্দুতে তৈরি আয়তাকার ঘরটিকে 'সেল' (যেমন: A1, B5) বলা হয়।

> ❓ **প্রশ্ন: এক্সেলে সূত্র (Formula) ও ফাংশন ব্যবহারের নিয়ম কী?**
> 💡 **উত্তর:** এক্সেলে যেকোনো সূত্র বা ফাংশন লেখার শুরুতে অবশ্যই সমান চিহ্ন (=) দিতে হয়। যেমন: দুটি সেলের যোগফলের সাধারণ সূত্র হলো =A1+B1 এবং রেঞ্জের যোগফলের ফাংশন হলো =SUM(A1:A10)।

