### ✍️ মূল পাঠ্যবইয়ের নমুনা বহুনির্বাচনি প্রশ্ন

1. কম্পিউটারে পেশাদার লেখালেখি ও ডকুমেন্ট তৈরির জন্য সবচেয়ে উপযুক্ত সফটওয়্যার কোনটি?
