ক. Ctrl + B    খ. Ctrl + I
গ. Ctrl + U    ঘ. Ctrl + K

3. ওয়ার্ডে লেখাকে বাঁকা (Italic) করতে কোন কীবোর্ড শর্টকাট ব্যবহার করা হয়?
ক. Ctrl + I    খ. Ctrl + B
গ. Ctrl + U    ঘ. Ctrl + E

4. ওয়ার্ড ডকুমেন্টে ভুল বানান চিহ্নিত ও সংশোধনের জন্য কোন টুলটি ব্যবহৃত হয়?
ক. Spelling & Grammar Checker    খ. Find and Replace
গ. Word Count    ঘ. Font Color

5. ডকুমেন্টের লেখায় পয়েন্ট আকারে তালিকা তৈরির জন্য কোন অপশনটি ব্যবহার করা হয়?
ক. Bullets and Numbering    খ. Drop Cap
গ. Watermark    ঘ. Header & Footer

6. তৈরিকৃত কোনো ডকুমেন্ট প্রথমবার সংরক্ষণ (Save) করতে কোন কীবোর্ড কমান্ড দেওয়া হয়?
ক. Ctrl + S    খ. Ctrl + O
গ. Ctrl + P    ঘ. Ctrl + N

7. স্প্রেডশিট সফটওয়্যারের ওয়ার্কশিটে উল্লম্ব বা খাড়া দাগের অংশগুলোকে কী বলা হয়?
ক. কলাম (Column)    খ. রো (Row)
গ. সেল (Cell)    ঘ. ওয়ার্কবুক

8. স্প্রেডশিটে একটি রো এবং একটি কলামের পরস্পর সংযোগস্থলে গঠিত ঘরটিকে কী বলা হয়?
ক. সেল (Cell)    খ. ব্লক
গ. পয়েন্টার    ঘ. রিবন

9. স্প্রেডশিটে কোনো হিসাবের সূত্র বা ফাংশন লেখার শুরুতে কোন চিহ্নটি বাধ্যতামূলক?
ক. = (সমান চিহ্ন)    খ. + (যোগ চিহ্ন)
গ. * (গুণ চিহ্ন)    ঘ. : (কোলন চিহ্ন)

10. এক্সেলে A1 সেল থেকে A10 সেল পর্যন্ত সকল সংখ্যার যোগফল নির্ণয়ের সঠিক ফাংশন কোনটি?
ক. =SUM(A1:A10)    খ. =TOTAL(A1:A10)
গ. =ADD(A1:A10)    ঘ. =PLUS(A1:A10)
