# ৫ম অধ্যায়: মাল্টিমিডিয়া ও গ্রাফিক্স

**তথ্য ও যোগাযোগ প্রযুক্তি • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*মাল্টিমিডিয়ার ধারণা ও উপাদান, প্রেজেন্টেশন সফটওয়্যার (পাওয়ারপয়েন্ট), অ্যাডোবি ফটোশপ (টুলবক্স, রেজোলিউশন, লেয়ার, কালার মোড) এবং অ্যাডোবি ইলাস্ট্রেটর।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> প্রেজেন্টেশন সফটওয়্যারের ধারণা ব্যাখ্যা করতে পারব;
> প্রেজেন্টেশন সফটওয়্যার ব্যবহারের গুরুতৃ বিশ্লেষণ করতে পারব;
> প্রেজেন্টেশন সফটওয়্যার ব্যবহারের কৌশল বর্ণনা করতে পারব;
> গ্রাফিক্স-এর ধারণা ব্যাখ্যা করতে পারব;
> গ্রাফিক্স সফটওয়্যার ব্যবহারের কৌশল বর্ণনা করতে পারব;
> প্রেজেন্টেশন সফটওয়্যার ব্যবহার করে বিষয় সংশ্লিষ্ট Slide তৈরি ও উপস্থাপন করতে পারব;
> গ্রাফিক্স সফটওয়্যার ব্যবহার করে সৃজনশীল চিত্র অঙ্কন ও উপস্থাপন করতে পারব |

মাল্টিমিডিয়া ও গ্রাফিক ve
### 🔹 বিষয়: মাল্টিমিডিয়ার ধারণা ও প্রধান মাধ্যমসমূহ
আদিকাল থেকেই মানুষ নিজেকে প্রকাশ করার জন্য বিভিন্ন মাধ্যম বা মিডিয়া ব্যবহার করছে। লেখা একটি
প্রকাশ মাধ্যম, শব্দ একটি প্রকাশ মাধ্যম আবার চিত্রও একটি প্রকাশ মাধ্যম | আমরা যখন অনেকগুলো প্রকাশ
