৫. আযানিমেশন: আযানিমেশন চলমান বা স্থির গ্রাফিক্স বা চিত্র। এটি দ্বিমাত্রিক বা ত্রিমাত্রিক হতে পারে।
বিজ্ঞাপন চিত্রে অ্যানিমেশনের ব্যবহার একটি জনপ্রিয় বিষয়। আযানিমেশন কখনোই কেবল একক মিডিয়া
হিসেবে ব্যবহৃত হয় না। অডিয়ো, ভিডিয়ো, টেক্সট, গ্রাফিক্স ইত্যাদির সমন্বয়ে সাধারণত অ্যানিমেশন তৈরি
হয়।
ঘিনি Gad, গ্রাফিক্স, অডিয়ো, ভিডিয়ো, অ্যানিমেশন ইত্যাদি নিয়ে কাজ করেন তিনিই মাল্টিমিডিয়া কনটেন্টস
ডেভেলপার। এই কাজটি করার জন্য এডোবি ফটোশপ থেকে থ্রিডি স্টুডিয়ো ম্যাক্স বা মায়া ইত্যাদি অনেক
সফটওয়্যার ব্যবহার করা হয়। বিভিন্ন কাজের জন্য বিভিন্ন সফটওয়্যার ব্যবহৃত হয়। কিন্তু বর্তমানের পরিপ্রেক্ষিত
বিবেচনা করে আমরা তাদেরকেই মাল্টিমিডিয়া প্রোগ্রামার বা মাল্টিমিডিয়া অথর বলবো যারা এসব মিডিয়া
ব্যবহার করে একটি ইন্টারআ্যাকটিভ ত্যাপ্রিকেশন তৈরি করেন | বস্তুত কনটেন্টস ডেভেলপ করা ও
ইন্টারআ্যাকটিভিটি যোগ করার মধ্যে বিশাল পার্থক্য রয়েছে। এডোবি প্রিমিয়ার বা এডোবি ফটোশপ এমন
সফটওয়্যার, যা দিয়ে একটি চমৎকার কনটেন্ট তৈরি করা যায়। কিন্তু আমরা মাল্টিমিডিয়া সফটওয়্যার
একটি ইন্টারআ্যাকটিভ আ্যাপ্রিকেশন তৈরি করা যায়।
আগামী দিনগুলোতে মাল্টিমিডিয়া প্রোগ্রামারের চাহিদা এবং সংখ্যা কোনোটাই কম হবে না। বিজনেস
সফটওয়্যার ও সার্ভিসেস-এর পাশাপাশি মাল্টিমিডিয়া কনটেন্টস ডেভেলপ করা ও প্রোগ্রামিং করতে পারা দক্ষ
লোকের চাহিদা বর্তমানে ব্যাপকভাবে বাড়ছে।
