প্রদান করলে এ অবজেক্ট পর্দায় পেস্ট হয় বা স্থাপিত হয়। অতঃপর সিলেকশন টুলের সাহায্যে Wit করে
কীবোর্ডের Alt বোতাম চেপে রেখে কোনো অবজেক্ট Wit করলে ওই অবজেক্টের হুবহু কপি তৈরি হয়ে
স্থানান্তরিত হয়।

এডিট মেনুর Paste In Front কমান্ড দিলে কপি করা অবজেক্ট Ue অবজেক্টের ঠিক উপর স্থাপিত হয়।
