লেয়ার
Layer শব্দের বাংলা হতে পারে স্তর। লেয়ার পদ্ধতিতে কাজ করার ক্ষেত্রে ভিন্ন ভিন্ন অবজেক্ট ভিন্ন ভিন্ন স্তরে
রেখে কাজ করা যায়। এই স্তর বা লেয়ারকে স্বচ্ছ কাচ, পলিথিন ইত্যাদির ACH তুলনা করা যেতে পারে।
তিনটি কাচের উপর বা অন্যান্য স্বচ্ছ মাধ্যমে তিনটি অবজেক্ট বা ছবি তৈরি করে একটির উপর একটি স্থাপন
