পরিবর্তন করা, কাজের সুবিধার্থে প্রয়োজন অনুযায়ী এক বা একাধিক অবজেক্ট অদৃশ্য করে রাখা, কাজের
সুবিধার্থে লেয়ার লক করে রাখা, নতুন লেয়ার যোগ করা এবং অপ্রয়োজনীয় লেয়ার বাতিল করা ইত্যাদি।
