### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: মাল্টিমিডিয়া কী এবং এর প্রধান উপাদানগুলো কী কী?**
> 💡 **উত্তর:** মানুষের ভাব প্রকাশের জন্য যখন দুই বা ততোধিক মাধ্যম (যেমন: বর্ণ বা টেক্সট, চিত্র বা গ্রাফিক্স এবং শব্দ বা অডিও) সমন্বিতভাবে ব্যবহৃত হয় তখন তাকে মাল্টিমিডিয়া বলে। এর প্রধান উপাদান তিনটি: (১) টেক্সট বা বর্ণ, (২) গ্রাফিক্স বা চিত্র (স্থির ও অ্যানিমেশন), এবং (৩) সাউন্ড বা অডিও।

> ❓ **প্রশ্ন: পাওয়ারপয়েন্টে প্রেজেন্টেশন স্লাইড প্রদর্শনের নিয়ম কী?**
> 💡 **উত্তর:** পাওয়ারপয়েন্টে প্রতিটি পৃষ্ঠাকে স্লাইড বলা হয়। প্রেজেন্টেশন সম্পূর্ণ স্ক্রিনে স্লাইড শো হিসেবে প্রদর্শনের জন্য কীবোর্ডের F5 বোতাম চাপতে হয়। পরবর্তী স্লাইডে যেতে স্পেসবার বা ডানমুখী তীরচিহ্ন এবং আগের স্লাইডে ফিরতে ব্যাকস্পেস বা বামমুখী তীরচিহ্ন ব্যবহৃত হয়।

> ❓ **প্রশ্ন: ফটোশপে RGB এবং CMYK কালার মোডের পার্থক্য কী?**
> 💡 **উত্তর:** RGB (Red, Green, Blue) কালার মোড কম্পিউটার স্ক্রিন, টেলিভিশন বা ইন্টারনেটে ডিজিটাল মাধ্যমে প্রদর্শনের জন্য ব্যবহৃত হয়। অন্যদিকে CMYK (Cyan, Magenta, Yellow, blacK) কালার মোড অফসেট প্রেস বা যেকোনো প্রকার কাগজের মুদ্রণ ও প্রকাশনার কাজের জন্য ব্যবহৃত হয়।

