# ৬ষ্ঠ অধ্যায়: প্রোগ্রামিংয়ের মাধ্যমে সমস্যার সমাধান

**তথ্য ও যোগাযোগ প্রযুক্তি • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*প্রোগ্রাম ও অ্যালগরিদম, ফ্লোচার্ট ও জ্যামিতিক প্রতীক, পাইথন (Python) প্রোগ্রামিংয়ের মৌলিক উপাদান (print, input, ভেরিয়েবল, ডেটা টাইপ, if-else শর্ত এবং while লুপ)।*

