### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> সমস্যা সমাধান সম্পর্কে জানতে পারব;
> পাইথন প্রোগ্রামিং ভাষা ব্যবহার করে কোডিং করতে পারব;

প্রোগ্রামিংয়ের মাধ্যমে সমস্যার সমাধান ১১১
কিন্ত শুধু ০ আর ১ দিয়ে নিজেদের নির্দেশগুলো লিখে ফেলাও আমাদের জন্য কঠিন। আমরা মানুষরা
সাধারণত যেসকল ভাষা ব্যবহার করি, সেগুলো শুধু ০ আর ১ দিয়ে তৈরি নয়। তাহলে কম্পিউটারের
করে নির্দেশ লিখলে কম্পিউটার সেই ভাষাকে সহজেই নিজের বোঝার উপযোগী হিসাবে রূপান্তর করে
নিয়ে নির্দেশগুলো বুঝতে পারে | এই ভাষাগুলোকে বলা হয় প্রোগ্রামিং ভাষা | অনেক রকম প্রোগ্রামিং
