রিলেশনাল এক্সপ্রেশন হয়। if (Condition) স্টেটমেন্টের পরে কোলন বসে।
এই Condition বা শর্তের মান যদি সত্য হয় তবে Body of if এ বর্ণিত কাজগুলো সম্পাদিত হবে। আর
যদি মিথ্যা হয় তাহলে Body of else এ বর্ণিত কাজসমূহ সম্পাদিত হয়। এখানে statements এ যে কোন
