### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: কম্পিউটার প্রোগ্রাম ও অ্যালগরিদম বলতে কী বোঝায়?**
> 💡 **উত্তর:** কোনো নির্দিষ্ট সমস্যা সমাধানের জন্য কম্পিউটারের বোধগম্য ভাষায় লিখিত ধারাবাহিক নির্দেশাবলিকে 'প্রোগ্রাম' বলে। আর সেই সমস্যাটি সমাধানের যুক্তিপূর্ণ ধারাবাহিক ধাপগুলোকে মানুষের বোঝার ভাষায় ধারাবাহিকভাবে লিপিবদ্ধ করাকে 'অ্যালগরিদম' বলে।

> ❓ **প্রশ্ন: ফ্লোচার্ট কী এবং এতে কোন কোন মৌলিক প্রতীক ব্যবহৃত হয়?**
> 💡 **উত্তর:** অ্যালগরিদমের ধাপগুলোকে যখন বিভিন্ন জ্যামিতিক প্রতীকের সাহায্যে চিত্ররূপ দেওয়া হয় তখন তাকে 'ফ্লোচার্ট' বলে। এর মৌলিক প্রতীকগুলো হলো: শুরু ও শেষের জন্য উপবৃত্ত (Oval), ইনপুট ও আউটপুটের জন্য সামান্তরিক (Parallelogram), প্রক্রিয়াকরণের জন্য আয়তক্ষেত্র (Rectangle), এবং শর্ত বা সিদ্ধান্তের জন্য হীরক/রম্বস (Diamond)।

> ❓ **প্রশ্ন: পাইথনে শর্তসাপেক্ষ স্টেটমেন্ট (if-else) এবং লুপের ভূমিকা কী?**
> 💡 **উত্তর:** পাইথনে কোনো শর্ত সত্য বা মিথ্যা হওয়ার ওপর ভিত্তি করে নির্দিষ্ট কোড সম্পাদনের জন্য 'if-else' স্টেটমেন্ট ব্যবহৃত হয়। আর একই কাজ বারবার স্বয়ংক্রিয়ভাবে সম্পাদনের জন্য 'while' বা 'for' লুপ ব্যবহৃত হয়।

