### ✍️ মূল পাঠ্যবইয়ের নমুনা বহুনির্বাচনি প্রশ্ন

1. কম্পিউটারের সাহায্যে সমস্যা সমাধানের জন্য লিখিত ধারাবাহিক নির্দেশমালাকে কী বলা হয়?
ক. প্রোগ্রাম (Program)    খ. হার্ডওয়্যার
গ. ফাইল সিস্টেম    ঘ. অ্যালবাম

2. সমস্যা সমাধানের ধারাবাহিক ধাপসমূহকে জ্যামিতিক চিত্রের মাধ্যমে উপস্থাপন করাকে কী বলে?
