ক. আয়তক্ষেত্র (Rectangle)    খ. সামান্তরিক
গ. রম্বস    ঘ. উপবৃত্ত

4. ফ্লোচার্টে কোনো সিদ্ধান্ত বা শর্ত (Decision Making) নির্দেশ করতে কোন প্রতীক ব্যবহৃত হয়?
ক. রম্বস বা ডায়মন্ড (Diamond)    খ. বৃত্ত
গ. আয়তক্ষেত্র    ঘ. তীরচিহ্ন

5. পাইথন প্রোগ্রামিং ভাষায় কোনো টেক্সট বা ফলাফল স্ক্রিনে প্রদর্শন করতে কোন ফাংশনটি ব্যবহৃত হয়?
ক. print()    খ. input()
গ. display()    ঘ. write()

6. পাইথনে ব্যবহারকারীর কাছ থেকে কীবোর্ডের মাধ্যমে ডেটা গ্রহণ করার ফাংশন কোনটি?
ক. input()    খ. get()
গ. read()    ঘ. scan()

