গ. switch    ঘ. case

8. একই নির্দেশ বা কাজের পুনরাবৃত্তি করার জন্য প্রোগ্রামিংয়ে কী ব্যবহৃত হয়?
ক. লুপ (Loop)    খ. কম্পাইলার
গ. অ্যারে    ঘ. পয়েন্টার

